SELECT id, txn_type, amount, txn_time, merchant, is_flagged, RANK() OVER (ORDER BY amount DESC NULLS LAST) AS amount_rank, ROUND(amount / SUM(amount) OVER (PARTITION BY account_id), 4) AS amount_share, ROUND(amount / SUM(amount) OVER (PARTITION BY txn_type), 4) AS amount_share_2, SUM(amount) OVER (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount FROM transactions;
